window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-19691\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρίψ, θριπός (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 644 na letra θ · nº geral 19691</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inseto que rói a madeira; caruncho.</p></section></article>\n<article id=\"entry-dgp-19692\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θριώ, οῦς</h1><div class=\"entry-meta\"><span>DGP · ordem 645 na letra θ · nº geral 19692</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Θρῖα.</p></section></article>\n<article id=\"entry-dgp-19693\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θριῶζε</h1><div class=\"entry-meta\"><span>DGP · ordem 646 na letra θ · nº geral 19693</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em direção a Tria. 〈Θριώ〉</p></section></article>\n<article id=\"entry-dgp-19694\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θροέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 647 na letra θ · nº geral 19694</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e aor. ἐθρόησα; pas. só pres., impf. e aor. ἐθροήθην) 1 gritar; dar gritos: παρὰ νοῦν θρ. sóf. dar gritos insensatos 2 falar; dizer; expressar 3 anunciar; revelar; proclamar ♦ méd. 4 fazer ouvir; gritar ♦ pas. 5 estar agitado, perturbado. 〈θρόος〉</p></section></article>\n<article id=\"entry-dgp-19695\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρόμβος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 648 na letra θ · nº geral 19695</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 coágulo (sangue) 2 grumo (leite coalhado) 3 grão (sal). 〈τρέφω〉</p></section></article>\n<article id=\"entry-dgp-19696\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρομβώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 649 na letra θ · nº geral 19696</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cheio de grumos. 〈θρόμβος〉</p></section></article>\n<article id=\"entry-dgp-19697\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρόνα, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 650 na letra θ · nº geral 19697</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 flores bordadas 2 ervas medicinais ou mágicas.</p></section></article>\n<article id=\"entry-dgp-19698\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρονιάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 651 na letra θ · nº geral 19698</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de Trônio. 〈Θρόνιον〉</p></section></article>\n<article id=\"entry-dgp-19699\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θρόνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 652 na letra θ · nº geral 19699</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Trônio, cidade da Lócrida.</p></section></article>\n<article id=\"entry-dgp-19700\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρόνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 653 na letra θ · nº geral 19700</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 assento com encosto; cadeira 2 trono (de rei ou deus) 3 dignidade real 4 assento da Pítia ou do deus do oráculo 5 assento de juiz 6 assento do professor, na escola 7 crist. assento do bispo; trono episcopal 8 tard., Astrol. combinação favorável das posições dos planetas.</p></section></article>\n<article id=\"entry-dgp-19701\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρόος, ου,</h1><div class=\"entry-meta\"><span>DGP · ordem 654 na letra θ · nº geral 19701</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. contr. θροῦς, οῦ (ὁ) 1 grito; clamor 2 som; concerto (música) 3 notícia que se propaga com rumor. 〈θρέομαι〉</p></section></article>\n<article id=\"entry-dgp-19702\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρυαλλίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 655 na letra θ · nº geral 19702</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pequena mecha de lamparina. 〈θρυαλλίς〉</p></section></article>\n<article id=\"entry-dgp-19703\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρυαλλίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 656 na letra θ · nº geral 19703</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tanchagem, planta medicinal 2 pavio de lamparina. 〈θρύον〉</p></section></article>\n<article id=\"entry-dgp-19704\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρυλέω</h1><div class=\"entry-meta\"><span>DGP · ordem 657 na letra θ · nº geral 19704</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e θρυλλέω-ῶ 1 murmurar; cochichar 2 repetir sem cessar; falar sem parar; tagarelar ♦ pas. 3 ser repetido: τὸ θρυλούμενον πολλοῖς artt. o que todo mundo repete, i.e., lugar-comum, αἱ τεθρυλημέναι γνῶμαι as máximas frequentemente repetidas. 〈θρῦλος〉</p></section></article>\n<article id=\"entry-dgp-19705\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρύλιγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 658 na letra θ · nº geral 19705</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fragmento; pedaço quebrado. 〈θρυλίζω〉</p></section></article>\n<article id=\"entry-dgp-19706\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρυλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 659 na letra θ · nº geral 19706</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">produzir uma nota falsa (na flauta). 〈θρῦλος〉</p></section></article>\n<article id=\"entry-dgp-19707\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρυλίσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 660 na letra θ · nº geral 19707</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., part. aor. θρυλίξας e aor. pas. 3ª sing. poét. θρυλίχθη) reduzir a pedaços; quebrar. 〈θρύλιγμα〉</p></section></article>\n<article id=\"entry-dgp-19708\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρυλλέω</h1><div class=\"entry-meta\"><span>DGP · ordem 661 na letra θ · nº geral 19708</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">θρυλέω.</p></section></article>\n<article id=\"entry-dgp-19709\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρῦλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 662 na letra θ · nº geral 19709</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">barulho; ruído; rumor.</p></section></article>\n<article id=\"entry-dgp-19710\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρῦμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 663 na letra θ · nº geral 19710</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fragmento; pedaço. 〈θρύπτω〉</p></section></article>\n<article id=\"entry-dgp-19711\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρυμματίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 664 na letra θ · nº geral 19711</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espécie de doce, de compota. 〈θρῦμμα〉</p></section></article>\n<article id=\"entry-dgp-19712\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρύον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 665 na letra θ · nº geral 19712</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 junco 2 espécie de tortulhos; cogumelo.</p></section></article>\n<article id=\"entry-dgp-19713\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρυπτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 666 na letra θ · nº geral 19713</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 capaz de quebrar, de moer 2 quebrantado; abatido 3 frágil; delicado 4 efeminado. 〈θρύπτω〉</p></section></article>\n<article id=\"entry-dgp-19714\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρυπτικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 667 na letra θ · nº geral 19714</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. molemente; brandamente; de modo relaxado.</p></section></article>\n<article id=\"entry-dgp-19715\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρύπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 668 na letra θ · nº geral 19715</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θρύψω, aor. ἔθρυψα; pas. fut. θρυφθήσομαι, aor.1 ἐθρύφθην, aor.2 rec. ἐθρύβην, perf. τέθρυμμαι) 1 reduzir a fragmentos; quebrar; esmigalhar 2 enfraquecer; enervar; desfibrar ♦ méd. pas. 3 ser despedaçado, esmigalhado 4 estar disperso, espalhado 5 enfraquecer-se: θρύπτεται ἡ ὄψις plut. a vista se enfraquece 6 entregar-se à devassidão 7 desfibrar-se: ἁπαλὸς καὶ τεθρυμμένος luc. mole e desfibrado 8 ter maneiras afetadas; fazer-se rogar 9 envaidecer-se; vangloriar-se de, dat. ou inf.</p></section></article>\n<article id=\"entry-dgp-19716\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρύψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 669 na letra θ · nº geral 19716</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de quebrar 2 quebrantamento; desencorajamento 3 moleza; delicadeza; efeminização. 〈θρύπτω〉</p></section></article>\n<article id=\"entry-dgp-19717\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρῴσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 670 na letra θ · nº geral 19717</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. θοροῦμαι, aor.2 ἔθορον) 1 lançar-se; saltar; pular: θρ. χαμᾶζε hom. saltar ao chão, ἐκ δίφροιο hom. saltar de um carro, κατὰ κῦμα hom. lançar-se nas ondas 2 arremessar-se em ataque; acometer com ímpeto: θρ. ἐπὶ Τρώεσσι hom. arremessar-se contra os troianos 3 adentrar atropeladamente; embarafustar-se: θρ. δόμους sóf. embarafustar-se pela casa.</p></section></article>\n<article id=\"entry-dgp-19718\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρωσμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 671 na letra θ · nº geral 19718</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">escarpamento; altura; elevação. 〈θρῴσκω〉</p></section></article>\n<article id=\"entry-dgp-19719\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 672 na letra θ · nº geral 19719</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">θυϊάς.</p></section></article>\n<article id=\"entry-dgp-19720\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θυάτειρα, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 673 na letra θ · nº geral 19720</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tiátira, cidade da Lídia.</p></section></article>\n<article id=\"entry-dgp-19721\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυγάτηρ, θυγατρός,</h1><div class=\"entry-meta\"><span>DGP · ordem 674 na letra θ · nº geral 19721</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">voc. θύγατερ, dat. θυγατρί, ac. θυγατέρα; pl. nom. θυγατέρες, gen. θυγατέρων, dat. θυγατράσι e ép. θυγατέρεσσιν, ac. θυγατέρας e ép. θύγατρας (ἡ) 1 filha 2 jovem; menina 3 serva; criada.</p></section></article>\n<article id=\"entry-dgp-19722\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυγατριδέος-οῦς, έου-οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 675 na letra θ · nº geral 19722</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">neto, filho da filha. 〈θυγάτηρ〉</p></section></article>\n<article id=\"entry-dgp-19723\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυγατριδέα-ῆ, έας-ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 676 na letra θ · nº geral 19723</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 neta, filha da filha 2 sobrinha. 〈θυγάτηρ〉</p></section></article>\n<article id=\"entry-dgp-19724\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυγατριδοῦς</h1><div class=\"entry-meta\"><span>DGP · ordem 677 na letra θ · nº geral 19724</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. de θυγατριδέος.</p></section></article>\n<article id=\"entry-dgp-19725\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυγάτριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 678 na letra θ · nº geral 19725</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filha pequena; filhinha. 〈θυγάτηρ〉</p></section></article>\n<article id=\"entry-dgp-19726\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θῦε</h1><div class=\"entry-meta\"><span>DGP · ordem 679 na letra θ · nº geral 19726</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. poét. de θύω1.</p></section></article>\n<article id=\"entry-dgp-19727\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυεία</h1><div class=\"entry-meta\"><span>DGP · ordem 680 na letra θ · nº geral 19727</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e θυΐα, ας (ἡ) 1 pilão 2 recipiente para amassar 3 taça do cótabo. 〈θύος〉</p></section></article>\n<article id=\"entry-dgp-19728\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυείδιον</h1><div class=\"entry-meta\"><span>DGP · ordem 681 na letra θ · nº geral 19728</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e θυίδιον, ου (τό) dim. de θυεία.</p></section></article>\n<article id=\"entry-dgp-19729\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύελλα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 682 na letra θ · nº geral 19729</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">borrasca; tempestade; vendaval. 〈θύω2〉</p></section></article>\n<article id=\"entry-dgp-19730\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θύεστα</h1><div class=\"entry-meta\"><span>DGP · ordem 683 na letra θ · nº geral 19730</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">eól. = Θυέστης.</p></section></article>\n<article id=\"entry-dgp-19731\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θυέστης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 684 na letra θ · nº geral 19731</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Tiestes, filho de Pélops e Hipodâmia, irmão de Atreu e pai de Egisto.</p></section></article>\n<article id=\"entry-dgp-19732\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θυεστιάδης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 685 na letra θ · nº geral 19732</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) filho de Tiestes, epít. de Egisto. 〈Θυέστης〉</p></section></article>\n<article id=\"entry-dgp-19733\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυήεις, ήεσσα, ῆεν</h1><div class=\"entry-meta\"><span>DGP · ordem 686 na letra θ · nº geral 19733</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que exala odor de incenso; perfumado; fragrante. 〈θύος〉</p></section></article>\n<article id=\"entry-dgp-19734\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυηλή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 687 na letra θ · nº geral 19734</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parte da vítima atirada ao fogo; oferta de sacrifício 2 primícias 3 sacrifício. 〈θύω1〉</p></section></article>\n<article id=\"entry-dgp-19735\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυηπολέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 688 na letra θ · nº geral 19735</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cumprir, realizar sacrifício aos deuses 2 ocupar-se de um sacrifício 3 oferecer em sacrifício: θυηπολεῖται δ᾽ ἄστυ μαντέων ὕπο eur. a cidade está sendo oferecida como vítima pelos adivinhos. 〈θυηπόλος〉</p></section></article>\n<article id=\"entry-dgp-19736\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυηπόλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 689 na letra θ · nº geral 19736</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que cumpre ou celebra sacrifícios 2 em Roma, que se ocupa de oferendas: αἱ θυηπόλοι παρθένοι as Virgens Vestais ♦ ὁ θυηπόλος 3 sacerdote que queima as oferendas, das quais tira presságios. 〈θύος, πολέω〉</p></section></article>\n<article id=\"entry-dgp-19737\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυηφάγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 690 na letra θ · nº geral 19737</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que devora a vítima do sacrifício (chama) 2 que consome o incenso. 〈θύος, φαγεῖν〉</p></section></article>\n<article id=\"entry-dgp-19738\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 691 na letra θ · nº geral 19738</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tuia; cedro.</p></section></article>\n<article id=\"entry-dgp-19739\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυϊάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 692 na letra θ · nº geral 19739</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 transportado de delírio báquico; inspirado 2 furioso como bacante ♦ ἡ θυϊάς 3 bacante; mênade.</p></section></article>\n<article id=\"entry-dgp-19740\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύϊνος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 693 na letra θ · nº geral 19740</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 de tuia; de cedro 2 feito da madeira do cedro. 〈θυία〉</p></section></article>\n<article id=\"entry-dgp-19741\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυλάκιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 694 na letra θ · nº geral 19741</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequeno saco 2 vagem onde estão os grãos. 〈θύλακος〉</p></section></article>\n<article id=\"entry-dgp-19742\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυλακίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 695 na letra θ · nº geral 19742</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vagem. 〈θύλακος〉</p></section></article>\n<article id=\"entry-dgp-19743\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύλακος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 696 na letra θ · nº geral 19743</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 saco; odre 2 saco; sacola de grãos 3 invólucro 4 saco onde ficam armazenadas as ovas do atum 5 calça larga dos persas.</p></section></article>\n<article id=\"entry-dgp-19744\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θῦλαξ, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 697 na letra θ · nº geral 19744</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">θύλακος.</p></section></article>\n<article id=\"entry-dgp-19745\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυλέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 698 na letra θ · nº geral 19745</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. oferecer em sacrifício. 〈θύω1〉</p></section></article>\n<article id=\"entry-dgp-19746\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυλήματα, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 699 na letra θ · nº geral 19746</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">oferendas atiradas ao fogo (incenso, bolo). 〈θυλέομαι〉</p></section></article>\n<article id=\"entry-dgp-19747\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θῦμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 700 na letra θ · nº geral 19747</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vítima ofertada em sacrifício 2 sacrifício: θ. τοῦ Ἀπόλλωνος tuc. sacrifício oferecido a Apolo, θ. λεύσιμον ésql. sacrifício de vítima por meio de apedrejamento 3 oferenda (de doces, frutos): θύματα ἐφέστια oferendas atiradas no fogo de Héstia 4 bolo para o sacrifício. 〈θύω1〉</p></section></article>\n<article id=\"entry-dgp-19748\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμαλγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 701 na letra θ · nº geral 19748</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que causa aflição; doloroso 2 aflito; consternado. 〈θυμός, ἀλγέω〉</p></section></article>\n<article id=\"entry-dgp-19749\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύμαλλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 702 na letra θ · nº geral 19749</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espécie de peixe.</p></section></article>\n<article id=\"entry-dgp-19750\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμαρής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 703 na letra θ · nº geral 19750</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agradável; encantador 2 caro; querido. 〈θυμός, ἀραρίσκω〉</p></section></article>\n<article id=\"entry-dgp-19751\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θύμβρις, ίδος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 704 na letra θ · nº geral 19751</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Tibre, rio da Itália 2 Timbris, rio ou monte da Sicília.</p></section></article>\n<article id=\"entry-dgp-19752\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμέλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 705 na letra θ · nº geral 19752</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 superfície do altar onde queimam as oferendas 2 altar de Dioniso, na orquestra do teatro em Atenas 3 teatro 4 cena 5 templo; monumento sagrado 6 pl. muros: θυμέλαι Κυκλώπων eur. muros dos Ciclopes, em Micenas. 〈θύω1〉</p></section></article>\n<article id=\"entry-dgp-19753\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμελικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 706 na letra θ · nº geral 19753</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do teatro; teatral; cênico ♦ οἱ θυμελικοί 2 coreutas ♦ τὸ θυμελικόν 3 estilo teatral; vulgar. 〈θυμέλη〉</p></section></article>\n<article id=\"entry-dgp-19754\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμηγερέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 707 na letra θ · nº geral 19754</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. pres. θυμηγερέων) reunir a força de seu coração; recuperar a coragem, o fôlego. 〈θυμός, ἀγείρω〉</p></section></article>\n<article id=\"entry-dgp-19755\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμηδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 708 na letra θ · nº geral 19755</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">agradável ao coração. 〈θυμός, ἦδος〉</p></section></article>\n<article id=\"entry-dgp-19756\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμηδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 709 na letra θ · nº geral 19756</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alegria do coração; satisfação. 〈θυμηδής〉</p></section></article>\n<article id=\"entry-dgp-19757\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμήρης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 710 na letra θ · nº geral 19757</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que alegra; agradável: θυμῆρες κεραν­νύναι hom. fazer uma mistura agradável ♦ θυμῆρες adv. 2 agradavelmente para encantar o coração. 〈θυμός, ἀρέσκω〉</p></section></article>\n<article id=\"entry-dgp-19758\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμίαμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 711 na letra θ · nº geral 19758</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 perfume (que queima); incenso 2 perfume para embalsamar os mortos. 〈θυμιάω〉</p></section></article>\n<article id=\"entry-dgp-19759\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμιατήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 712 na letra θ · nº geral 19759</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">porta-incenso; defumador; turíbulo. 〈θυμιάω〉</p></section></article>\n<article id=\"entry-dgp-19760\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 713 na letra θ · nº geral 19760</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 queimar para produzir fumaça: στύρακα θ. her. queimar resina 2 intr. queimar incenso 3 intr. fumegar: ἄνθρακες θιμιῶντες teofr. carvões fumegantes ♦ méd. 4 queimar perfumes em honra de, dat. ♦ pas. 5 converter-se em fumo. 〈θῦμα〉</p></section></article>\n<article id=\"entry-dgp-19761\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμίημα, θυμιητήριον</h1><div class=\"entry-meta\"><span>DGP · ordem 714 na letra θ · nº geral 19761</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = θυμίαμα, θυμιατήριον.</p></section></article>\n<article id=\"entry-dgp-19762\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 715 na letra θ · nº geral 19762</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem muito ardor no coração; ardente 2 que se deixa dominar pelo ardor no coração; irascível. 〈θυμός〉</p></section></article>\n<article id=\"entry-dgp-19763\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 716 na letra θ · nº geral 19763</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com paixão; com vivacidade 2 com irritação; com animosidade.</p></section></article>\n<article id=\"entry-dgp-19764\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμοβόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 717 na letra θ · nº geral 19764</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que corrói, atormenta o coração. 〈θυμός, βιβρώσκω〉</p></section></article>\n<article id=\"entry-dgp-19765\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμοδακής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 718 na letra θ · nº geral 19765</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que morde o coração. 〈θυμός, δάκνω 〉</p></section></article>\n<article id=\"entry-dgp-19766\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 719 na letra θ · nº geral 19766</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cheio de ardor; resoluto; corajoso 2 irascível; litigante ♦ τὸ θυμοειδές 3 impetuosidade; ímpeto 4 ânimo irascível, passional. 〈θυμός, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-19767\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμολέων, οντος</h1><div class=\"entry-meta\"><span>DGP · ordem 720 na letra θ · nº geral 19767</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de coração de leão. 〈θυμός, λέων〉</p></section></article>\n<article id=\"entry-dgp-19768\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμόμαντις, εως</h1><div class=\"entry-meta\"><span>DGP · ordem 721 na letra θ · nº geral 19768</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que prevê pela força de seu coração, conforme seu ânimo (e não por inspiração divina). 〈θυμός, μάντις〉</p></section></article>\n<article id=\"entry-dgp-19769\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμομαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 722 na letra θ · nº geral 19769</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lutar com ardor, com ímpeto, com obstinação 2 irritar-se por algo, ἐπί e dat., contra alguém, πρός e ac. 〈θυμός, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-19770\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύμον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 723 na letra θ · nº geral 19770</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tomilho, planta odorífera 2 mistura de tomilho, vinagre e mel ou, segundo alguns, cebola selvagem, comida dos pobres em Atenas 3 Medic. cisto sebáceo; lúpia.</p></section></article>\n<article id=\"entry-dgp-19771\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμοπληθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 724 na letra θ · nº geral 19771</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cheio de ardor, de ímpeto no coração. 〈θυμός, πλῆθος〉</p></section></article>\n<article id=\"entry-dgp-19772\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμοραϊστής, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 725 na letra θ · nº geral 19772</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que dilacera o coração; cruel. 〈θυμός, ῥαΐζω〉</p></section></article>\n<article id=\"entry-dgp-19773\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμός, οῦ (ὁ) 1</h1><div class=\"entry-meta\"><span>DGP · ordem 726 na letra θ · nº geral 19773</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alma como princípio da vida; sopro vital; vida 2 alma como princípio ou sede da vontade; vontade; desejo 3 coração como sede da inteligência; ânimo; mente 4 coração como sede de sentimentos e paixões; íntimo 5 ânimo; ardor; ímpeto 6 impetuosidade; ímpeto; animosidade 1 ὀλίγος δ᾽ ἔτι θυμὸς ἐνῆν hom. ainda havia dentro de mim um pouco de vida, ἀπὸ δ᾽ ἔπτατο θυμός hom. e a alma voou embora 2 θ. ἀνώγει ou κελεύει hom. o coração me incita a, inf., θ. ἐστί ou γίγνεταί μοι her. é meu desejo, inf., σφι θυμὸς ἐγένετο θεήσασθαι τὸν πόλεμον her. foi desejo deles contemplar a guerra, ἤθελε θυμῷ hom. ele desejava em seu coração, οἱ θυμὸς ἐβούλετο hom. seu coração queria, οἱ θυμὸς ἐφορμᾶται γαμέεσθαι hom. o coração a impelia a casar-se, ὥς σοι θυμός sóf. como é teu desejo, i.e., como te apraz, πλησάμενος θυμὸν ἐδητύος ἠδὲ ποτῆτος hom. satisfeito em seu desejo de comida e de bebida 3 ᾔδεε γὰρ κατὰ θυμόν hom. ele sabia em seu coração, τοὺς ἐμοὺς λόγους θυμῷ βάλε ésql. lança em teu coração minhas palavras 4 ἕνα θυμὸν ἔχοντες hom. tendo um único sentimento, θυμὸν ὀρίνειν hom. excitar a alma, i.e., provocar a piedade, o temor, νεμεσιζέσθω ἐνὶ θυμῷ hom. que ele se irrite em seu coração, χαίρειν θυμῷ ou ἐν θυμῷ hom. alegrar-se em seu coração, ἄχνυτο θυμός hom. o coração se afligia, θυμὸς ἐφορμᾶται πολεμίζειν ἠδὲ μάχεσθαι hom. meu coração arde por combater e guerrear, ἄχος ou ἄλγος ἱκάνει θυμόν hom. a dor domina meu coração, ἐκ θυμοῦ ou θυμῷ φιλέειν hom. amar de coração, de todo o coração, δέος ἔμπεσε θυμῷ hom. o temor invadiu seu coração, σιδηρόφρων θυμὸς ἀνδρείᾳ φλέγων ésql. ânimo férreo, ardente de coragem 5 θυμὸν λαμβάνειν hom. tomar ânimo, θυμὸν ἔχειν ἀγαθόν her. ter tranqüilo o ânimo, ἴωμεν ῥώμῃ καὶ θυμῷ ἐπὶ τοὺς πολεμίους xen. avancemos com vigor e coragem contra os inimigos, ἐν τοῖς δεινοῖς θυμὸν οὐκ ἀπώλεσεν sóf. não perdeu ânimo nos perigos 6 δάμασον θυμὸν μέγαν hom. domina sua intensa animosidade, θ. ὀξύς sóf. ímpeto violento, θυμὸν ἐκχεῖν luc. extravasar sua impetuosidade. 〈θύω2〉</p></section></article>\n<article id=\"entry-dgp-19774\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύμος1, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 727 na letra θ · nº geral 19774</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 = θύμον 2 = θύμος2.</p></section></article>\n<article id=\"entry-dgp-19775\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύμος2, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 728 na letra θ · nº geral 19775</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medic. cisto sebáceo; lúpia.</p></section></article>\n<article id=\"entry-dgp-19776\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμόσοφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 729 na letra θ · nº geral 19776</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de ânimo sensato; inteligente; engenhoso ♦ τὸ θυμόσοφον 2 docilidade. 〈θυμός, σοφός〉</p></section></article>\n<article id=\"entry-dgp-19777\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμοφθορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 730 na letra θ · nº geral 19777</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter o espírito atormentado. 〈θυμοφ­θόρος〉</p></section></article>\n<article id=\"entry-dgp-19778\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμοφθόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 731 na letra θ · nº geral 19778</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que destrói o ânimo, a vida 2 que mata; mortífero 3 que oprime; molesto; lastimável 4 funesto; mau 5 que tem o espírito alterado; furioso; louco. 〈θυμός, φθείρω〉</p></section></article>\n<article id=\"entry-dgp-19779\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 732 na letra θ · nº geral 19779</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 irritar ♦ méd. pas. (méd. fut. θυμώσομαι, aor. ἐθυμώθην) 2 irritar-se; estar irritado; enfurecer-se contra alguém, dat., ἐς e ac., contra algo, ἐπί e dat., a respeito de, gen., dat., περί e gen.: θυμοῦσθαι εἰς κέρας eur. [touro] ameaçar com chifres furiosos ♦ τὸ θυμούμενον tuc. 3 impetuosidade. 〈θυμός〉</p></section></article>\n<article id=\"entry-dgp-19780\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυμώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 733 na letra θ · nº geral 19780</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ardente; corajoso; impetuoso 2 irascível; insubmisso; violento. 〈θυμός〉</p></section></article>\n<article id=\"entry-dgp-19781\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύμωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 734 na letra θ · nº geral 19781</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ímpeto de cólera. 〈θυμόω〉</p></section></article>\n<article id=\"entry-dgp-19782\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυννευτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 735 na letra θ · nº geral 19782</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adequado à pesca do atum. 〈θύννος〉</p></section></article>\n<article id=\"entry-dgp-19783\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυννοκέφαλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 736 na letra θ · nº geral 19783</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com cabeça de atum. 〈θύννος, κεφαλή〉</p></section></article>\n<article id=\"entry-dgp-19784\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύννος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 737 na letra θ · nº geral 19784</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">atum, peixe. 〈θύνω〉</p></section></article>\n<article id=\"entry-dgp-19785\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυννοσκόπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 738 na letra θ · nº geral 19785</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que espreita os atuns. 〈θύννος, σκοπέω〉</p></section></article>\n<article id=\"entry-dgp-19786\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυννώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 739 na letra θ · nº geral 19786</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estúpido como um atum. 〈θύννος〉</p></section></article>\n<article id=\"entry-dgp-19787\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 740 na letra θ · nº geral 19787</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. poét. θῦνον)1 lançar-se com impetuosidade; pular; saltar 2 mudar repentinamente de uma coisa, ac., para outra, ἐπί e ac.: ἐπ᾽ ἄλλοτ᾽ ἄλλον θύνει λόγον pínd. passar de um relato para outro. 〈θύω2〉</p></section></article>\n<article id=\"entry-dgp-19788\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 741 na letra θ · nº geral 19788</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que exala perfume; fragrante. 〈θύος〉</p></section></article>\n<article id=\"entry-dgp-19789\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 742 na letra θ · nº geral 19789</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tuia, árvore odorífera 2 incenso 3 bolo para um sacrifício. 〈θύος〉</p></section></article>\n<article id=\"entry-dgp-19790\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 743 na letra θ · nº geral 19790</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ger. pl. oferenda para um sacrifício 2 ger. pl. sacrifício 3 incenso. 〈θύω1〉</p></section></article>\n";
